162	    /**
163	     * Returns the stored E.164 {@code telephone} formatted for humans: the recognized country code
164	     * (with its leading {@code '+'}), a space, then the national digits grouped in threes from the
165	     * left and separated by spaces (for example {@code '+61412345678'} renders as
166	     * {@code '+61 412 345 678'}). The split into country code and national number reuses
167	     * {@link #countryCodeOf(String)}, the single definition of that split. Returns {@code null} when
168	     * the owner has no telephone, and returns the raw E.164 value unchanged when it carries no
169	     * recognized country code. This is the single definition of an owner's human-readable telephone.
170	     *
171	     * @return the human-formatted telephone, or {@code null} when the owner has no telephone
172	     */
173	    @Transient
174	    public String getTelephoneDisplay() {
175	        if (this.telephone == null) {
176	            return null;
177	        }
178	        String countryCode = countryCodeOf(this.telephone);
179	        if (countryCode == null) {
180	            return this.telephone;
181	        }
182	        String national = this.telephone.substring(1 + countryCode.length());
183	        StringBuilder display = new StringBuilder("+").append(countryCode);
184	        for (int i = 0; i < national.length(); i += 3) {
185	            display.append(' ').append(national, i, Math.min(i + 3, national.length()));
186	        }
187	        return display.toString();
188	    }
