298	    /**
299	     * Builds the derived identity key that consolidates all owner duplicate detection into a
300	     * single value: the normalized E.164 {@code telephone}, the lower-cased {@code email}
301	     * (empty when none) and the {@code householdId} (empty when the owner shares no household),
302	     * joined by {@code '|'}. Two owners are duplicates exactly when their whole identity keys are
303	     * equal, so a difference in any of the three parts (for example two household mates with
304	     * different telephones) yields distinct keys. A {@code null} part contributes the empty string.
305	     *
306	     * @param telephone the normalized E.164 telephone
307	     * @param email the lower-cased email, or {@code null} when none
308	     * @param householdId the shared household identifier, or {@code null} when none
309	     * @return the derived identity key
310	     */
311	    public static String identityKey(String telephone, String email, String householdId) {
312	        return (telephone == null ? "" : telephone) + "|"
313	            + (email == null ? "" : email) + "|"
314	            + (householdId == null ? "" : householdId);
315	    }
316	
317	    /**
318	     * Returns this owner's derived identity key, see
319	     * {@link #identityKey(String, String, String)}.
320	     *
321	     * @return the derived identity key for this owner
322	     */
323	    @Transient
324	    public String getIdentityKey() {
325	        return identityKey(this.telephone, this.email, this.householdId);
326	    }
327	
328	    /**
329	     * Fixed telephone country-code table: the exact national-number length (the count of digits
330	     * following the country code) each country code this application recognizes admits
331	     * ({@code '61'} Australia => 9, {@code '1'} NANP => 10). Keyed by the country-code digits
332	     * without the leading {@code '+'}. A country code absent from this table is not recognized.
333	     */
334	    private static final Map<String, Integer> COUNTRY_CODE_NATIONAL_LENGTHS = Map.of("61", 9, "1", 10);
335	
336	    /**
337	     * Resolves the recognized country code a normalized E.164 telephone carries: the longest entry
338	     * of the fixed country-code table (see {@link #COUNTRY_CODE_NATIONAL_LENGTHS}) whose digits the
339	     * number begins with, so a shorter code can never shadow a longer one. Returns the country-code
340	     * digits without the leading {@code '+'} (for example {@code '61'} for {@code '+61412345678'}),
341	     * or {@code null} when the value is {@code null}, carries no leading {@code '+'}, or begins with
342	     * no recognized country code. This is the single definition of how an E.164 telephone splits
343	     * from its country code, shared by every rule that reasons about a telephone's country code.
344	     *
345	     * @param telephone the normalized E.164 telephone (a {@code '+'} followed by digits), or {@code null}
346	     * @return the recognized country-code digits, or {@code null} when none is recognized
347	     */
348	    public static String countryCodeOf(String telephone) {
349	        if (telephone == null || !telephone.startsWith("+")) {
350	            return null;
351	        }
352	        String digits = telephone.substring(1);
353	        return COUNTRY_CODE_NATIONAL_LENGTHS.keySet().stream()
354	            .filter(digits::startsWith)
355	            .max(Comparator.comparingInt(String::length))
356	            .orElse(null);
357	    }
358	
359	    /**
360	     * Resolves the exact national-number length (the count of digits following the country code) a
361	     * recognized country code admits using the fixed country-code table ({@code '61'} => 9,
362	     * {@code '1'} => 10, see {@link #COUNTRY_CODE_NATIONAL_LENGTHS}). Returns the length, or
363	     * {@code null} when the country code is {@code null} or not recognized (it then carries no
364	     * per-country length rule). This is the single definition of the per-country national-number
365	     * lengths, shared by every rule that relates a telephone's national number to its country code.
366	     *
367	     * @param countryCode the country-code digits without the leading {@code '+'}, or {@code null}
368	     * @return the required national-number length, or {@code null} when the code is not recognized
369	     */
370	    public static Integer nationalNumberLength(String countryCode) {
371	        return countryCode == null ? null : COUNTRY_CODE_NATIONAL_LENGTHS.get(countryCode);
372	    }
373	
374	    /**
375	     * Fixed city-to-region table: the canonical region each known city belongs to
376	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}). A city
377	     * absent from this table has no known region.
378	     */
379	    private static final Map<String, String> CITY_REGIONS = Map.of(
380	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
381	
382	    /**
383	     * Resolves the canonical region a city belongs to using the fixed city-to-region table
384	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}). Returns the
385	     * region string, or {@code null} when the city has no known region. This is the single
386	     * definition of the city-to-region mapping, shared by every rule that derives a region
387	     * from an owner's city.
388	     *
389	     * @param city the city to resolve
390	     * @return the canonical region, or {@code null} when the city has no known region
391	     */
392	    public static String regionForCity(String city) {
393	        return CITY_REGIONS.get(city);
394	    }
395	
396	    /**
397	     * Fixed region-to-postcode table: the inclusive {@code {low, high}} 4-digit postcode range
398	     * each region admits ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}).
399	     * A region absent from this table has no fixed range.
400	     */
401	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
402	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
403	
404	    /**
405	     * Resolves the inclusive {@code {low, high}} 4-digit postcode range a region admits using the
406	     * fixed region-to-postcode table ({@code NSW 2000-2099}, {@code VIC 3000-3099},
407	     * {@code QLD 4000-4099}). Returns the range, or {@code null} when the region is {@code null} or
408	     * has no fixed range (any 4-digit postcode is then admitted). This is the single definition of
409	     * the region-to-postcode ranges, shared by every rule that relates a postcode to a region.
410	     *
411	     * @param region the region to resolve, or {@code null}
412	     * @return the inclusive {@code {low, high}} range, or {@code null} when the region has none
413	     */
414	    public static int[] postcodeRangeForRegion(String region) {
415	        return region == null ? null : REGION_POSTCODE_RANGES.get(region);
416	    }
417	
418	    /**
419	     * Resolves the canonical region a postcode belongs to by finding the fixed region-to-postcode
420	     * range that contains it ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}).
421	     * Returns the region string, or {@code null} when the postcode is {@code null}, not a 4-digit
422	     * value, or falls in no known range. This is the single definition of the postcode-to-region
423	     * mapping, shared by every rule that derives a region from a postcode.
424	     *
425	     * @param postcode the postcode to resolve
426	     * @return the canonical region, or {@code null} when the postcode maps to no known region
427	     */
428	    public static String regionForPostcode(String postcode) {
429	        if (postcode == null || !postcode.matches("^[0-9]{4}$")) {
430	            return null;
431	        }
432	        int value = Integer.parseInt(postcode);
433	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
434	            int[] range = entry.getValue();
435	            if (value >= range[0] && value <= range[1]) {
436	                return entry.getKey();
437	            }
438	        }
439	        return null;
440	    }
441	
442	    /**
443	     * Returns the canonical region this owner belongs to. The owner's {@code postcode} is preferred:
444	     * when it falls in a known region range (see {@link #regionForPostcode(String)}) that region is
445	     * used, disambiguating cities that share a name. Only when the postcode is absent or in no known
446	     * range does derivation fall back to the fixed city-to-region table (see
447	     * {@link #regionForCity(String)}). Returns {@code null} when neither the postcode nor the city
448	     * resolves to a known region. This is the single definition of an owner's region, shared by
449	     * every rule that derives a region from an owner.
450	     *
451	     * @return the owner's canonical region, or {@code null} when it has no known region
452	     */
453	    @Transient
454	    public String getRegion() {
455	        String region = regionForPostcode(this.postcode);
456	        return region != null ? region : regionForCity(this.city);
457	    }
458	
459	    /**
460	     * Resolves whether an {@code email} counts as present for membership purposes: the value is
461	     * non-null and not blank. Returns {@code false} otherwise. This is the single definition of an
462	     * owner "having an email", shared by every rule that turns email presence into a derived value
463	     * (its membership factor and its {@code contactPreference}).
464	     *
465	     * @param email the owner's email, or {@code null}
466	     * @return {@code true} when the email is present and not blank
467	     */
468	    public static boolean hasEmail(String email) {
469	        return email != null && !email.isBlank();
470	    }
471	
472	    /**
473	     * Resolves whether an owner with the given {@code namesakeCount} has no namesakes: the count is
474	     * present and equal to {@code 0}. Returns {@code false} when the count is {@code null} (unknown)
475	     * or positive. This is the single definition of the "no namesakes" membership factor, shared by
476	     * every rule that rewards an owner for being unique by name.
477	     *
478	     * @param namesakeCount the owner's namesake count, or {@code null}
479	     * @return {@code true} when the owner is known to have no namesakes
480	     */
481	    public static boolean hasNoNamesakes(Integer namesakeCount) {
482	        return namesakeCount != null && namesakeCount == 0;
483	    }
484	
485	    /**
486	     * Resolves the fiscal year a date falls in. The fiscal year starts on 1 July, so a date in July
487	     * through December belongs to the fiscal year of the following calendar year, while a date in
488	     * January through June belongs to the fiscal year of its own calendar year (for example both
489	     * 2025-08-01 and 2026-03-01 fall in fiscal year 2026). This is the single definition of the
490	     * date-to-fiscal-year mapping, shared by every value derived on a fiscal-year basis (the
491	     * {@code fiscalYear}, the membership number's year segment and tenure).
492	     *
493	     * @param date the date to resolve, never {@code null}
494	     * @return the fiscal year the date falls in
495	     */
496	    public static int fiscalYearOf(LocalDate date) {
497	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
498	    }
499	
500	    /**
501	     * Resolves whether an owner registered on {@code registrationDate} has long tenure as of
502	     * {@code asOf}: the number of elapsed fiscal years between the two dates (see
503	     * {@link #fiscalYearOf(LocalDate)}) exceeds {@code 1}. Returns {@code false} when
504	     * {@code registrationDate} is absent, so the owner has no derivable tenure; because a newly
505	     * created owner has zero elapsed fiscal years, it never counts as long-tenured. This is the
506	     * single definition of the "long tenure" membership factor, shared by every rule that rewards
507	     * an owner for tenure beyond a fiscal year.
508	     *
509	     * @param registrationDate the owner's registration date, or {@code null}
510	     * @param asOf the date the tenure is measured against
511	     * @return {@code true} when the owner's tenure exceeds one elapsed fiscal year
512	     */
513	    public static boolean hasLongTenure(LocalDate registrationDate, LocalDate asOf) {
514	        return registrationDate != null && fiscalYearOf(asOf) - fiscalYearOf(registrationDate) > 1;
515	    }
516	
517	    /**
518	     * Resolves whether an owner with the given {@code householdMemberCount} belongs to a large
519	     * household: the count is present and at least {@code 3}. Returns {@code false} when the count is
520	     * {@code null} (unknown) or smaller. This is the single definition of the "large household"
521	     * membership factor, shared by every rule that rewards an owner for a household of three or more.
522	     *
523	     * @param householdMemberCount the number of owners sharing the household, or {@code null}
524	     * @return {@code true} when the owner is known to belong to a household of three or more
525	     */
526	    public static boolean hasLargeHousehold(Integer householdMemberCount) {
527	        return householdMemberCount != null && householdMemberCount >= 3;
528	    }
529	
530	    /**
531	     * Returns this owner's membership points. Points start at {@code 0} and accumulate the membership
532	     * factors: {@code 2} when an email is present, {@code 1} when the owner has no namesakes
533	     * (namesakeCount is 0), {@code 2} when the owner belongs to a household of three or more, and
534	     * {@code 3} when the owner's tenure exceeds one elapsed fiscal year. Because a newly created
535	     * owner has zero tenure, the tenure points are never awarded on creation. This is the single source the
536	     * membership level is derived from (see {@link #getMembershipLevel()}).
537	     *
538	     * @return the owner's membership points
539	     */
540	    @Transient
541	    public Integer getMembershipPoints() {
542	        LocalDate today = LocalDate.now();
543	        int points = 0;
544	        if (hasEmail(this.email)) {
545	            points += 2;
546	        }
547	        if (hasNoNamesakes(this.namesakeCount)) {
548	            points += 1;
549	        }
550	        if (hasLargeHousehold(this.householdMemberCount)) {
551	            points += 2;
552	        }
553	        if (hasLongTenure(this.registrationDate, today)) {
554	            points += 3;
555	        }
556	        return points;
557	    }
558	
559	    /**
560	     * Resolves the numeric membership level a given number of membership points earns: {@code 1} for
561	     * {@code 0-1} points, {@code 2} for {@code 2-3}, {@code 3} for {@code 4-5}, and {@code 4} for
562	     * {@code 6} or more points. This is the single definition of the points-to-level mapping, shared
563	     * by every rule that derives a membership level from points (see {@link #getMembershipLevel()}).
564	     *
565	     * @param points the membership points to map
566	     * @return the membership level those points earn
567	     */
568	    public static int membershipLevelForPoints(int points) {
569	        if (points >= 6) {
570	            return 4;
571	        }
572	        if (points >= 4) {
573	            return 3;
574	        }
575	        if (points >= 2) {
576	            return 2;
577	        }
578	        return 1;
579	    }
580	
581	    /**
582	     * Applies an owner's household level ceiling to a membership level: the level is returned
583	     * unchanged when {@code cap} is {@code null} (no ceiling applies), otherwise it is capped at
584	     * {@code cap} so it can never exceed it. This is the single definition of how the household
585	     * level ceiling caps a membership level, shared by every rule that reads a capped membership
586	     * level (see {@link #getMembershipLevel()}).
587	     *
588	     * @param level the uncapped membership level derived from the owner's points
589	     * @param cap the owner's household level ceiling, or {@code null} when no ceiling applies
590	     * @return the membership level after applying the ceiling
591	     */
592	    public static int cappedMembershipLevel(int level, Integer cap) {
593	        return cap == null ? level : Math.min(level, cap);
594	    }
595	
596	    /**
597	     * Returns this owner's numeric membership level, derived from its membership points (see
598	     * {@link #getMembershipPoints()}) by the single points-to-level mapping (see
599	     * {@link #membershipLevelForPoints(int)}): {@code 1} for {@code 0-1} points, {@code 2} for
600	     * {@code 2-3}, {@code 3} for {@code 4-5}, and {@code 4} for {@code 6} or more points. The
601	     * result is then held to the owner's household level ceiling {@code membershipLevelCap} (see
602	     * {@link #cappedMembershipLevel(int, Integer)}): a new owner joining a household may earn a
603	     * level at most one above the highest level among its existing household members, and no
604	     * ceiling applies when the owner joined an empty household.
605	     *
606	     * @return the owner's membership level, capped by its household level ceiling
607	     */
608	    @Transient
609	    public Integer getMembershipLevel() {
610	        return cappedMembershipLevel(membershipLevelForPoints(getMembershipPoints()), this.membershipLevelCap);
611	    }
612	
613	    /**
614	     * Returns this owner's fiscal year formatted as {@code 'FY<YY>'}, where YY is the last two digits
615	     * of the fiscal year (starting 1 July, see {@link #fiscalYearOf(LocalDate)}) the owner's
616	     * business-day-adjusted {@code registrationDate} falls in, e.g. {@code 'FY26'}. Returns
617	     * {@code null} when the owner has no registration date, so the fiscal year cannot be derived.
618	     * This is the single definition of an owner's fiscal year, shared by every value derived on a
619	     * fiscal-year basis (see {@link #getMembershipNumber()}).
620	     *
621	     * @return the owner's fiscal year, or {@code null} when it cannot be derived
622	     */
623	    @Transient
624	    public String getFiscalYear() {
625	        if (this.registrationDate == null) {
626	            return null;
627	        }
628	        return String.format("FY%02d", fiscalYearOf(this.registrationDate) % 100);
629	    }
630	
631	    /**
632	     * Returns this owner's membership number formatted as {@code '<customerCode>-M<YY>'}, where YY is
633	     * the last two digits of the fiscal year (see {@link #fiscalYearOf(LocalDate)}) the owner's
634	     * business-day-adjusted {@code registrationDate} falls in, e.g. {@code 'NSW-A1B2C3D4-M26'}.
635	     * Returns {@code null} when the owner has no customer code or registration date.
636	     *
637	     * @return the owner's membership number, or {@code null} when it cannot be derived
638	     */
639	    @Transient
640	    public String getMembershipNumber() {
641	        if (this.customerCode == null || this.registrationDate == null) {
642	            return null;
643	        }
644	        return String.format("%s-M%02d", this.customerCode, fiscalYearOf(this.registrationDate) % 100);
645	    }
646	
647	    /**
648	     * Returns this owner's check digit: a single Luhn check digit (0-9) over the digits contained in
649	     * the owner's customerCode. Returns {@code null} when the owner has no customer code.
650	     *
651	     * @return the owner's check digit, or {@code null} when it has no customer code
652	     */
653	    @Transient
654	    public Integer getCheckDigit() {
655	        if (this.customerCode == null) {
656	            return null;
657	        }
658	        String code = this.customerCode;
659	        int sum = 0;
660	        boolean dbl = true;
661	        for (int i = code.length() - 1; i >= 0; i--) {
662	            char c = code.charAt(i);
663	            if (c < '0' || c > '9') {
664	                continue;
665	            }
666	            int d = c - '0';
667	            if (dbl) {
668	                d *= 2;
669	                if (d > 9) {
670	                    d -= 9;
671	                }
672	            }
673	            sum += d;
674	            dbl = !dbl;
675	        }
676	        return (10 - (sum % 10)) % 10;
677	    }
678	
679	    /**
680	     * Returns this owner's age band, derived from {@code birthDate} computed against
681	     * {@code registrationDate}: the whole number of years between the two dates places the owner in
682	     * {@code 'MINOR'} (under 18), {@code 'ADULT'} (18 to 64 inclusive) or {@code 'SENIOR'} (65 or
683	     * older). Returns {@code null} when the owner has no birth date or no registration date, so the
684	     * band cannot be derived. This is the single definition of an owner's age band.
685	     *
686	     * @return the owner's age band, or {@code null} when it cannot be derived
687	     */
688	    @Transient
689	    public String getAgeBand() {
690	        if (this.birthDate == null || this.registrationDate == null) {
691	            return null;
692	        }
693	        int age = java.time.Period.between(this.birthDate, this.registrationDate).getYears();
694	        if (age < 18) {
695	            return "MINOR";
696	        }
697	        if (age < 65) {
698	            return "ADULT";
699	        }
700	        return "SENIOR";
701	    }
702	
703	    protected Set<Pet> getPetsInternal() {
704	        if (this.pets == null) {
705	            this.pets = new HashSet<>();
706	        }
707	        return this.pets;
708	    }
709	
710	    protected void setPetsInternal(Set<Pet> pets) {
711	        this.pets = pets;
712	    }
713	
714	    public List<Pet> getPets() {
715	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
716	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
717	        return Collections.unmodifiableList(sortedPets);
718	    }
719	
720	    public void setPets(List<Pet> pets) {
721	        this.pets = new HashSet<>(pets);
722	    }
723	
724	    public void addPet(Pet pet) {
725	        getPetsInternal().add(pet);
726	        pet.setOwner(this);
727	    }
728	
729	    /**
730	     * Return the Pet with the given name, or null if none found for this Owner.
731	     *
732	     * @param name to test
733	     * @return true if pet name is already in use
734	     */
735	    public Pet getPet(String name) {
736	        return getPet(name, false);
737	    }
738	
739	    /**
740	     * Return the Pet with the given name, or null if none found for this Owner.
741	     *
742	     * @param name to test
743	     * @return true if pet name is already in use
744	     */
745	    public Pet getPet(String name, boolean ignoreNew) {
746	        name = name.toLowerCase();
747	        for (Pet pet : getPetsInternal()) {
748	            if (!ignoreNew || !pet.isNew()) {
749	                String compName = pet.getName();
750	                compName = compName.toLowerCase();
751	                if (compName.equals(name)) {
752	                    return pet;
753	                }
754	            }
755	        }
756	        return null;
757	    }
758	
759	    public Pet getPet(Integer petId) {
760	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
761	    }
762	
763	    @Override
764	    public String toString() {
765	        return new ToStringCreator(this)
766	
767	            .append("id", this.getId())
768	            .append("new", this.isNew())
769	            .append("lastName", this.getLastName())
770	            .append("firstName", this.getFirstName())
771	            .append("address", this.address)
772	            .append("city", this.city)
773	            .append("telephone", this.telephone)
774	            .append("email", this.email)
775	            .toString();
776	    }
777	}
