285	        currentOwner.setLastName(ownerFieldsDto.getLastName());
286	        currentOwner.setTitle(ownerFieldsDto.getTitle());
287	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
288	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
289	        this.clinicService.saveOwner(currentOwner);
290	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
291	    }
292	
293	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
294	    @Transactional
295	    @Override
296	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
297	        Owner owner = this.clinicService.findOwnerById(ownerId);
298	        if (owner == null) {
299	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
300	        }
301	        owner.setDeleted(true);
302	        this.clinicService.saveOwner(owner);
303	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
304	    }
305	
306	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
307	    @Override
308	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
309	        Owner owner = this.clinicService.findOwnerById(ownerId);
310	        if (owner == null) {
311	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
312	        }
313	        HttpHeaders headers = new HttpHeaders();
314	        Pet pet = petMapper.toPet(petFieldsDto);
315	        owner.setId(ownerId);
316	        pet.setOwner(owner);
317	        pet.getType().setName(null);
318	        this.clinicService.savePet(pet);
319	        PetDto petDto = petMapper.toPetDto(pet);
320	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
321	            .buildAndExpand(pet.getId()).toUri());
322	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
323	    }
324	
325	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
326	    @Override
327	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
328	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
329	        if (currentOwner != null) {
330	            Pet currentPet = this.clinicService.findPetById(petId);
331	            if (currentPet != null) {
