394	    /**
395	     * Applies an owner's address to the submitted fields, normalizing it in place into the
396	     * canonical form stored and returned for the owner. This is the single intake step that owns
397	     * how a submitted address becomes an owner's stored address: it delegates every transform to
398	     * {@link #normalizeAddress(String)}, the single definition of address normalization, and writes
399	     * the results back onto {@code ownerFieldsDto}.
400	     *
401	     * <p>The structured fields are preferred when supplied: when a non-blank {@code addressLine1}
402	     * is present the two structured lines are normalized in place and the flat {@code address} is
403	     * (re)composed from them — the normalized {@code addressLine1}, with a single space and the
404	     * normalized {@code addressLine2} appended only when an {@code addressLine2} was supplied — so
405	     * every rule that later reads {@code address} sees the structured value. When no structured
406	     * {@code addressLine1} is supplied the flat {@code address} is normalized in place, preserving
407	     * backward compatibility.
408	     *
409	     * <p>It runs ahead of {@link #validateRequiredFields(OwnerFieldsDto)} so an address that is
410	     * blank after normalization in either form is rejected by the required-field check that
411	     * follows. Isolating the step here keeps {@link #prepareNewOwner(OwnerFieldsDto, LocalDate)} a
412	     * list of named intake steps and gives address handling one place to grow.
413	     *
414	     * @param ownerFieldsDto the submitted owner fields, whose address is normalized in place
415	     */
416	    private void applyAddress(OwnerFieldsDto ownerFieldsDto) {
417	        String line1 = ownerFieldsDto.getAddressLine1();
418	        if (line1 != null && !line1.isBlank()) {
419	            String normalizedLine1 = normalizeAddress(line1);
420	            ownerFieldsDto.setAddressLine1(normalizedLine1);
421	            String line2 = ownerFieldsDto.getAddressLine2();
422	            if (line2 != null && !line2.isBlank()) {
423	                String normalizedLine2 = normalizeAddress(line2);
424	                ownerFieldsDto.setAddressLine2(normalizedLine2);
425	                ownerFieldsDto.setAddress(normalizedLine1 + " " + normalizedLine2);
426	            } else {
427	                ownerFieldsDto.setAddressLine2(null);
428	                ownerFieldsDto.setAddress(normalizedLine1);
429	            }
430	        } else {
431	            ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
432	        }
433	    }
