506	    /**
507	     * Counts the existing owners whose adjusted business-day {@code registrationDate} equals the
508	     * given date. This is the single definition of the per-day owner count, shared by the per-day
509	     * create limit ({@link #rejectDailyLimitExceeded(LocalDate)}) and the bulk-signup warning
510	     * ({@link #bulkSignupWarning(LocalDate)}), so both accumulate owners against a day identically.
511	     *
512	     * @param registrationDate the adjusted business-day registration date to count owners against
513	     * @return the number of existing owners carrying that registration date
514	     */
515	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
516	        return this.clinicService.findAllOwners().stream()
517	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
518	            .count();
519	    }
