610	    /**
611	     * Counts the existing owners that share the given {@code firstName} and {@code lastName}
612	     * with the owner being created, compared case-insensitively. The count is taken before the
613	     * new owner is persisted, so it reflects only pre-existing owners and never includes the new
614	     * owner itself. The resulting value is stored on the owner and exposed as {@code namesakeCount}.
615	     *
616	     * @param firstName the first name of the owner being created
617	     * @param lastName the last name of the owner being created
618	     * @return the number of pre-existing owners sharing the same first and last name
619	     */
620	    private int countNamesakes(String firstName, String lastName) {
621	        return (int) this.clinicService.findAllOwners().stream()
622	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
623	                && lastName.equalsIgnoreCase(existing.getLastName()))
624	            .count();
625	    }
