654	    /**
655	     * Finds the existing owner, if any, that makes the given newly created owner a possible (soft)
656	     * duplicate: an owner sharing its {@code lastName} (compared case-insensitively) and its
657	     * {@code postcode} while carrying a different (normalized) {@code telephone}. This is the single
658	     * definition of the soft-duplicate match; {@link #applyPossibleDuplicate(Owner, OwnerFieldsDto)} only records the
659	     * outcome on the owner. An owner without a postcode can share no postcode and matches nothing, so
660	     * {@link java.util.Optional#empty()} is returned.
661	     *
662	     * @param owner the owner being created, already carrying its normalized telephone and postcode
663	     * @return the matching existing owner, or {@link java.util.Optional#empty()} when none matches
664	     */
665	    private java.util.Optional<Owner> findPossibleDuplicate(Owner owner) {
666	        if (owner.getPostcode() == null) {
667	            return java.util.Optional.empty();
668	        }
669	        return this.clinicService.findAllOwners().stream()
670	            .filter(existing -> !Owner.isDeleted(existing.getDeleted()))
671	            .filter(existing -> owner.getLastName().equalsIgnoreCase(existing.getLastName())
672	                && owner.getPostcode().equals(existing.getPostcode())
673	                && !owner.getTelephone().equals(existing.getTelephone()))
674	            .findFirst();
675	    }
