677	    /**
678	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city}
679	     * or {@code telephone} is missing or blank. A field that is only whitespace is treated as
680	     * blank. When any field fails, a {@link RequiredFieldsMissingException} is thrown carrying
681	     * the names of every offending field, which the exception advice renders as a 400 response
682	     * with an {@code errors} array.
683	     *
684	     * @param ownerFieldsDto the submitted owner fields
685	     */
686	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
687	        List<String> missing = new ArrayList<>();
688	        addIfBlank(missing, "firstName", ownerFieldsDto.getFirstName());
689	        addIfBlank(missing, "lastName", ownerFieldsDto.getLastName());
690	        addIfBlank(missing, "address", ownerFieldsDto.getAddress());
691	        addIfBlank(missing, "city", ownerFieldsDto.getCity());
692	        addIfBlank(missing, "telephone", ownerFieldsDto.getTelephone());
693	        if (!missing.isEmpty()) {
694	            throw new RequiredFieldsMissingException(missing);
695	        }
696	    }
