704	    /**
705	     * Normalizes a submitted telephone number into E.164 form. Spaces, dashes and brackets
706	     * are stripped. When a leading {@code '+'} and country code are present they are kept as
707	     * given; otherwise the country code {@code '+61'} is assumed and a single leading
708	     * {@code '0'} is dropped from the national digits. The result must be a {@code '+'}
709	     * followed by 8 to 15 digits. The normalized E.164 value is what gets stored and returned.
710	     * When the value cannot form a valid E.164 number an {@link InvalidFieldsException} is
711	     * thrown, which the exception advice renders as a 400 response naming the {@code telephone}
712	     * field. For example {@code "0412 345 678"} becomes {@code "+61412345678"}.
713	     *
714	     * @param telephone the submitted telephone value
715	     * @return the normalized E.164 telephone
716	     */
717	    private String normalizeTelephone(String telephone) {
718	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
719	        String e164;
720	        if (cleaned.startsWith("+")) {
721	            e164 = "+" + cleaned.substring(1);
722	        } else {
723	            String national = cleaned;
724	            if (national.startsWith("0")) {
725	                national = national.substring(1);
726	            }
727	            e164 = "+61" + national;
728	        }
729	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
730	            throw new InvalidFieldsException(List.of("telephone"));
731	        }
732	        validateNationalNumberLength(e164);
733	        return e164;
734	    }
735	
736	    /**
737	     * Validates the national-number length of an already syntactically valid E.164 telephone
738	     * against its country code. When the number carries a country code this application recognizes
739	     * (see {@link Owner#countryCodeOf(String)}) the digits following that code must have exactly the
740	     * length that code admits ({@code '+61'} => 9 national digits, {@code '+1'} => 10, see
741	     * {@link Owner#nationalNumberLength(String)}). When the country code is recognized but the
742	     * national number is the wrong length an {@link InvalidFieldsException} is thrown, which the
743	     * exception advice renders as a 400 response naming the {@code telephone} field. A country code
744	     * that is not recognized carries no per-country length rule and is left to the general
745	     * 8-to-15-digit E.164 check.
746	     *
747	     * @param e164 the normalized E.164 telephone (a {@code '+'} followed by digits)
748	     */
749	    private void validateNationalNumberLength(String e164) {
750	        String countryCode = Owner.countryCodeOf(e164);
751	        if (countryCode == null) {
752	            return;
753	        }
754	        int nationalLength = e164.length() - 1 - countryCode.length();
755	        if (nationalLength != Owner.nationalNumberLength(countryCode)) {
756	            throw new InvalidFieldsException(List.of("telephone"));
757	        }
758	    }
