760	    /**
761	     * Pattern for a syntactically valid email address: a non-empty local part, an {@code @},
762	     * and a domain containing at least one dot, none of the parts holding whitespace or a
763	     * second {@code @}.
764	     */
765	    private static final java.util.regex.Pattern EMAIL_PATTERN =
766	        java.util.regex.Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
767	
768	    /**
769	     * Disposable email domains an owner may not register with. An email whose domain (compared
770	     * case-insensitively) is one of these is rejected, since it identifies a throwaway mailbox.
771	     */
772	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS =
773	        java.util.Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
774	
775	    /**
776	     * Normalizes an optional owner email. An email is optional, so a {@code null} value is
777	     * accepted and returned unchanged. When present it must be a syntactically valid address
778	     * whose domain is not on the disposable-domain blocklist (see
779	     * {@link #DISPOSABLE_EMAIL_DOMAINS}); the value is stored and returned lower-cased. When
780	     * present but syntactically invalid or on a disposable domain an
781	     * {@link InvalidFieldsException} is thrown, which the exception advice renders as a 400
782	     * response naming the {@code email} field.
783	     *
784	     * @param email the submitted email value, or {@code null} when omitted
785	     * @return the lower-cased email, or {@code null} when none was supplied
786	     */
787	    private String normalizeEmail(String email) {
788	        if (email == null) {
789	            return null;
790	        }
791	        String trimmed = email.trim();
792	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
793	            throw new InvalidFieldsException(List.of("email"));
794	        }
795	        String domain = trimmed.substring(trimmed.lastIndexOf('@') + 1).toLowerCase(java.util.Locale.ROOT);
796	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
797	            throw new InvalidFieldsException(List.of("email"));
798	        }
799	        return canonicalEmail(trimmed);
800	    }
