802	    /**
803	     * Reduces an email to the canonical form used both to store it and to compare it against
804	     * other owners' emails: surrounding whitespace is trimmed and the value is lower-cased. A
805	     * {@code null} email (none was supplied) canonicalizes to {@code null}. Unlike
806	     * {@link #normalizeEmail(String)} no validation is performed, so this can be applied to a
807	     * value read back off an existing owner without risk of rejecting it. This is the single
808	     * definition of email identity: two emails denote the same address exactly when they
809	     * canonicalize to the same value, so an email stored via {@link #normalizeEmail(String)} and
810	     * an email already on an existing owner can be compared for equality after both pass through
811	     * here. For example {@code "  Jane@Example.COM "} canonicalizes to {@code "jane@example.com"}.
812	     *
813	     * @param email the email to canonicalize, or {@code null} when none was supplied
814	     * @return the trimmed, lower-cased email, or {@code null} when {@code email} is {@code null}
815	     */
816	    private String canonicalEmail(String email) {
817	        if (email == null) {
818	            return null;
819	        }
820	        return email.trim().toLowerCase(java.util.Locale.ROOT);
821	    }
