823	    /**
824	     * Validates an optional owner postcode. A postcode is optional, so a {@code null} value is
825	     * accepted and left unchanged. When present it must be exactly 4 digits, and when the owner's
826	     * city has a known region (see {@link Owner#regionForCity(String)}) the postcode must fall
827	     * within that region's inclusive range ({@code NSW 2000-2099}, {@code VIC 3000-3099},
828	     * {@code QLD 4000-4099}, see {@link Owner#postcodeRangeForRegion(String)}). A city with no known
829	     * region admits any 4-digit postcode. When present but malformed or out of range for the city's
830	     * region an {@link InvalidFieldsException} is thrown, which the exception advice renders as a
831	     * 400 response naming the {@code postcode} field.
832	     *
833	     * @param postcode the submitted postcode, or {@code null} when omitted
834	     * @param city the owner's city, used to resolve the region whose range the postcode must satisfy
835	     */
836	    private void validatePostcode(String postcode, String city) {
837	        if (postcode == null) {
838	            return;
839	        }
840	        if (!postcode.matches("^[0-9]{4}$")) {
841	            throw new InvalidFieldsException(List.of("postcode"));
842	        }
843	        int[] range = Owner.postcodeRangeForRegion(Owner.regionForCity(city));
844	        if (range != null) {
845	            int value = Integer.parseInt(postcode);
846	            if (value < range[0] || value > range[1]) {
847	                throw new InvalidFieldsException(List.of("postcode"));
848	            }
849	        }
850	    }
851	
852	    /**
853	     * Rejects a new owner that is an exact identity duplicate of an existing owner. An owner's
854	     * identity is its derived identity key (see {@link #identityKey(String, String, String)}) — its
855	     * normalized {@code telephone}, canonical {@code email} and shared {@code householdId} joined by
856	     * {@code '|'} — so a new owner is a hard duplicate only when an existing, non-deleted owner
857	     * matches it on all three. Two owners that merely share a household (the same last name and
858	     * postcode) but differ in telephone or email are distinct owners and are not rejected here; such a
859	     * near-match is instead recorded as a soft {@code possibleDuplicate} (see
860	     * {@link #applyPossibleDuplicate(Owner, OwnerFieldsDto)}). When an existing owner shares the new
861	     * owner's identity key a {@link DuplicateIdentityException} is thrown, which the exception advice
862	     * renders as a 409 Conflict response. Setting {@code sharesHousehold} declares the owner a
863	     * deliberate household member and bypasses this block. An owner without a postcode belongs to no
864	     * shared household and is never a duplicate here.
865	     *
866	     * @param ownerFieldsDto the submitted owner fields, already normalized in place
867	     */
868	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto) {
869	        if (sharesHousehold(ownerFieldsDto)) {
870	            return;
871	        }
872	        String householdId = householdIdFor(ownerFieldsDto.getLastName(), ownerFieldsDto.getPostcode());
873	        if (householdId == null) {
874	            return;
875	        }
876	        String identityKey = identityKey(ownerFieldsDto.getTelephone(), ownerFieldsDto.getEmail(), householdId);
877	        boolean taken = householdMembers(householdId).stream()
878	            .filter(existing -> !Owner.isDeleted(existing.getDeleted()))
879	            .anyMatch(existing -> identityKey.equals(
880	                identityKey(existing.getTelephone(), existing.getEmail(), existing.getHouseholdId())));
881	        if (taken) {
882	            throw new DuplicateIdentityException(identityKey);
883	        }
884	    }
885	
886	    /**
887	     * Builds the identity key that decides whether two owners denote the same identity: their
888	     * normalized {@code telephone}, canonical {@code email} (see {@link #canonicalEmail(String)}) and
889	     * shared {@code householdId}, joined by {@code '|'}. This is the single definition of owner
890	     * identity used by {@link #rejectDuplicateIdentity(OwnerFieldsDto)}; two owners are the same
891	     * identity exactly when their keys are equal, so a value stored on an existing owner and the
892	     * fields submitted for a new owner can be compared for identity after both pass through here.
893	     *
894	     * @param telephone the owner's normalized telephone
895	     * @param email the owner's email, or {@code null} when none was supplied
896	     * @param householdId the owner's shared household identifier
897	     * @return the identity key
898	     */
899	    private String identityKey(String telephone, String email, String householdId) {
900	        return telephone + "|" + canonicalEmail(email) + "|" + householdId;
901	    }
902	
903	    /**
904	     * Assigns the deterministic shared {@code householdId} to a newly created owner. The identifier
905	     * is derived from the owner's household identity — its {@code lastName} and {@code postcode} (see
906	     * {@link #householdIdFor(String, String)}) — so every owner sharing a last name and postcode
907	     * resolves to the same stable value automatically, without any explicit linking. An owner without
908	     * a postcode belongs to no shared household and is left without a household identifier.
909	     *
910	     * @param owner the newly created owner, mutated in place with its household identifier
911	     */
912	    private void assignHousehold(Owner owner) {
913	        owner.setHouseholdId(householdIdFor(owner.getLastName(), owner.getPostcode()));
914	    }
915	
916	    /**
917	     * Reports whether a submitted owner opted into sharing a household, i.e. whether its request
918	     * carried {@code sharesHousehold} set to {@code true}. A {@code null} or {@code false} flag is
919	     * not opting in. This is the single reading of the {@code sharesHousehold} intent, shared by
920	     * every rule that treats a declared household member differently from an independent owner.
921	     *
922	     * @param ownerFieldsDto the submitted owner fields carrying the {@code sharesHousehold} flag
923	     * @return {@code true} when the request opted into sharing a household
924	     */
925	    private boolean sharesHousehold(OwnerFieldsDto ownerFieldsDto) {
926	        return Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
927	    }
928	
929	    /**
930	     * Derives the stable {@code householdId} shared by every owner in the household identified by
931	     * the given {@code lastName} and {@code postcode}. The household is keyed on {@code (lastName,
932	     * postcode)}: the normalized last name and the postcode are hashed with SHA-256 and the leading
933	     * 12 hex characters of the digest form the identifier, so any two owners sharing a last name and
934	     * postcode — regardless of creation order or address — resolve to the same identifier
935	     * automatically. An owner without a postcode belongs to no shared household, so {@code null} is
936	     * returned.
937	     *
938	     * @param lastName the household's last name
939	     * @param postcode the household's postcode, or {@code null} when the owner has none
940	     * @return the deterministic household identifier, or {@code null} when {@code postcode} is {@code null}
941	     */
942	    private String householdIdFor(String lastName, String postcode) {
943	        if (postcode == null) {
944	            return null;
945	        }
946	        return shaHex(householdKey(lastName, postcode), 12);
947	    }
948	
949	    /**
950	     * Builds the canonical household key that identifies the household a {@code lastName} and
951	     * {@code postcode} belong to: the normalized last name (case-insensitive, with collapsed
952	     * whitespace) joined to the postcode by {@code '|'}. This is the single definition of which
953	     * owner fields make up a household and how they are normalized;
954	     * {@link #householdIdFor(String, String)} hashes this key into the stored identifier, so any two
955	     * owners in the same household resolve to the same key and therefore the same identifier.
956	     *
957	     * @param lastName the household's last name
958	     * @param postcode the household's postcode
959	     * @return the normalized household key
960	     */
961	    private String householdKey(String lastName, String postcode) {
962	        return collapseWhitespace(lastName).toLowerCase(java.util.Locale.ROOT) + "|" + postcode;
963	    }
964	
965	    /**
966	     * Computes the upper-case hex SHA-256 digest of a string, truncated to its first
967	     * {@code hexChars} characters. The input is hashed as UTF-8 bytes and each digest byte is
968	     * rendered as two upper-case hex digits, so {@code hexChars} characters cover the leading
969	     * {@code ceil(hexChars / 2)} bytes of the digest. This is the single definition of the
970	     * SHA-256 hex derivation shared by every rule that hashes owner fields (for example the
971	     * household identifier). SHA-256 is a required platform algorithm; were it ever unavailable
972	     * an {@link IllegalStateException} is thrown.
973	     *
974	     * @param input the string to hash
975	     * @param hexChars the number of leading upper-case hex characters to return
976	     * @return the first {@code hexChars} upper-case hex characters of the SHA-256 digest
977	     */
978	    private String shaHex(String input, int hexChars) {
979	        try {
980	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
981	                .digest(input.getBytes(java.nio.charset.StandardCharsets.UTF_8));
982	            StringBuilder sb = new StringBuilder();
983	            for (int i = 0; i < digest.length && sb.length() < hexChars; i++) {
984	                sb.append(String.format("%02X", digest[i]));
985	            }
986	            return sb.substring(0, hexChars);
987	        }
988	        catch (java.security.NoSuchAlgorithmException e) {
989	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
990	        }
991	    }
992	
993	    /**
994	     * Returns the owners that belong to the household identified by the given {@code householdId},
995	     * i.e. every owner carrying that exact identifier. Soft-deleted owners are included, so a caller
996	     * that must ignore deleted owners (as {@link #rejectDuplicateIdentity(OwnerFieldsDto)} does)
997	     * filters them out itself. The owners are taken from the current set, so after a create the
998	     * result includes the newly persisted owner. An owner without a household (a {@code null}
999	     * identifier) belongs to no shared household, so an empty list is returned. This is the single
1000	     * definition of a household's members, shared by every rule that reasons about the owners
1001	     * sharing a household (the household-duplicate block and the household member count).
1002	     *
1003	     * @param householdId the shared household identifier, or {@code null} when the owner shares no household
1004	     * @return the owners in the household, or an empty list when {@code householdId} is {@code null}
1005	     */
1006	    private List<Owner> householdMembers(String householdId) {
1007	        if (householdId == null) {
1008	            return List.of();
1009	        }
1010	        return this.clinicService.findAllOwners().stream()
1011	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
1012	            .collect(Collectors.toList());
1013	    }
1014	
1015	    /**
1016	     * Counts the owners that belong to the household identified by the given {@code householdId} (see
1017	     * {@link #householdMembers(String)}), i.e. every owner carrying that exact identifier. The count
1018	     * is taken against the current set of owners, so after a create it reflects the household's size
1019	     * including the newly persisted owner. An owner without a household (a {@code null} identifier)
1020	     * belongs to no shared household and yields {@code 0}.
1021	     *
1022	     * @param householdId the shared household identifier, or {@code null} when the owner shares no household
1023	     * @return the number of owners in the household, or {@code 0} when {@code householdId} is {@code null}
1024	     */
1025	    private int countHouseholdMembers(String householdId) {
1026	        return householdMembers(householdId).size();
1027	    }
1028	
1029	    /**
1030	     * Stamps an owner with its household member count, the number of owners sharing its household
1031	     * (see {@link #countHouseholdMembers(String)}), so every value the owner derives from its
1032	     * household size (its membership factor and level) reads a populated count rather than the
1033	     * unstamped default. This is the single definition of hydrating an owner with its household
1034	     * member count, shared by the create and read paths that render an owner's derived values.
1035	     *
1036	     * @param owner the owner to stamp, mutated in place with its household member count
1037	     */
1038	    private void applyHouseholdMemberCount(Owner owner) {
1039	        owner.setHouseholdMemberCount(countHouseholdMembers(owner.getHouseholdId()));
1040	    }
1041	
1042	    /**
1043	     * Resolves the household level ceiling a newly created owner is subject to: one above the
1044	     * current maximum {@code membershipLevel} among the existing, non-deleted owners already
1045	     * sharing its household (see {@link #householdMembers(String)}). Each existing member is
1046	     * stamped with its household member count first so its {@link Owner#getMembershipLevel()}
1047	     * reads a populated count, mirroring how the create and read paths render a member's derived
1048	     * level. The ceiling is taken before the new owner is persisted, so it reflects only the
1049	     * members already in the household. When the owner joins an empty household — no household
1050	     * identifier, or no existing member — no ceiling applies and {@code null} is returned, letting
1051	     * the owner earn its uncapped level (see {@link Owner#cappedMembershipLevel(int, Integer)}).
1052	     *
1053	     * @param householdId the shared household identifier of the owner being created, or {@code null}
1054	     * @return one above the household's current maximum membership level, or {@code null} when no ceiling applies
1055	     */
1056	    private Integer householdMembershipLevelCap(String householdId) {
1057	        java.util.OptionalInt max = householdMembers(householdId).stream()
1058	            .filter(existing -> !Owner.isDeleted(existing.getDeleted()))
1059	            .peek(this::applyHouseholdMemberCount)
1060	            .mapToInt(Owner::getMembershipLevel)
1061	            .max();
1062	        return max.isPresent() ? max.getAsInt() + 1 : null;
1063	    }
1064	
1065	    /**
1066	     * Collapses a field for household comparison: leading and trailing whitespace is trimmed and
1067	     * every internal run of whitespace is reduced to a single space. A {@code null} value collapses
1068	     * to the empty string. Case is left untouched so callers can compare case-insensitively.
1069	     *
1070	     * @param value the value to collapse, or {@code null}
1071	     * @return the whitespace-collapsed value, never {@code null}
1072	     */
1073	    private String collapseWhitespace(String value) {
1074	        if (value == null) {
1075	            return "";
1076	        }
1077	        return value.trim().replaceAll("\\s+", " ");
1078	    }
1079	
1080	    /**
1081	     * Common street-type abbreviations expanded during address normalization, keyed by their
1082	     * upper-cased token.
1083	     */
1084	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS =
1085	        java.util.Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
1086	
1087	    /**
1088	     * Normalizes a submitted address into the canonical form stored and returned for an owner:
1089	     * leading and trailing whitespace is trimmed, every internal run of whitespace is collapsed to
1090	     * a single space, the value is upper-cased, and common street-type abbreviations are expanded
1091	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value
1092	     * normalizes to the empty string, and an address that holds only whitespace normalizes to the
1093	     * empty string so the required-field check rejects it. For example {@code "  12  main  st "}
1094	     * becomes {@code "12 MAIN STREET"}. This is the single definition of address normalization used
1095	     * everywhere an address is stored or compared.
1096	     *
1097	     * @param address the submitted address value, or {@code null}
1098	     * @return the normalized address, never {@code null}
1099	     */
1100	    private String normalizeAddress(String address) {
1101	        if (address == null) {
1102	            return "";
1103	        }
1104	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
1105	        if (collapsed.isEmpty()) {
1106	            return "";
1107	        }
1108	        String[] tokens = collapsed.split(" ");
1109	        StringBuilder sb = new StringBuilder(collapsed.length());
1110	        for (int i = 0; i < tokens.length; i++) {
1111	            if (i > 0) {
1112	                sb.append(' ');
1113	            }
1114	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
1115	        }
1116	        return sb.toString();
1117	    }
1118	}
