28	    OwnerDto toOwnerDto(Owner owner);
29	
30	    /**
31	     * Derives the owner's {@code selfLink}: the canonical URI path of the owner, formed as
32	     * {@code '/api/owners/'} followed by its id. Returns {@code null} when the owner has no id
33	     * yet, leaving {@code selfLink} absent from the response.
34	     */
35	    default String selfLink(Owner owner) {
36	        if (owner == null || owner.getId() == null) {
37	            return null;
38	        }
39	        return "/api/owners/" + owner.getId();
40	    }
41	
42	    /**
43	     * Derives the owner's age band as the DTO enum, rendering the owner's derived age band (see
44	     * {@link Owner#getAgeBand()}). Returns {@code null} when the owner has no derivable age band
45	     * (no birthDate or no registrationDate), leaving {@code ageBand} absent from the response.
46	     */
47	    default OwnerDto.AgeBandEnum ageBand(Owner owner) {
48	        if (owner == null || owner.getAgeBand() == null) {
49	            return null;
50	        }
51	        return OwnerDto.AgeBandEnum.valueOf(owner.getAgeBand());
52	    }
53	
54	    /**
55	     * Derives the owner's preferred contact channel: {@code 'EMAIL'} when an email address
56	     * is present (non-null and non-blank), otherwise {@code 'PHONE'}.
57	     */
58	    default OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
59	        if (owner == null) {
60	            return null;
61	        }
62	        return Owner.hasEmail(owner.getEmail())
63	            ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
64	    }
65	
66	    /**
67	     * Derives the owner's locality from the region its identity carries (see
68	     * {@link #localityRegion(Owner)}). Returns that region string, or {@code 'UNKNOWN'} when the
69	     * owner has no known region.
70	     */
71	    default String locality(Owner owner) {
72	        if (owner == null) {
73	            return null;
74	        }
75	        String region = localityRegion(owner);
76	        return region != null ? region : "UNKNOWN";
77	    }
78	
79	    /**
80	     * Resolves the region an owner's {@link #locality(Owner)} is derived from. This is the
81	     * {@code REGION} segment carried by the owner's {@code customerCode}, whose new
82	     * {@code '<REGION>-<HASH8>'} identity encodes the region ahead of the first {@code '-'}. The
83	     * sentinel {@code 'UNKNOWN'} region (used when the owner has no known region) and a missing
84	     * customer code both resolve to {@code null}. Keeping the region source in its own method leaves
85	     * {@link #locality(Owner)} owning only the {@code null -> 'UNKNOWN'} rendering, so where the
86	     * region itself comes from can change without disturbing that rendering.
87	     *
88	     * @param owner the owner whose locality region is resolved, never {@code null}
89	     * @return the region string, or {@code null} when the owner has no known region
90	     */
91	    default String localityRegion(Owner owner) {
92	        String code = owner.getCustomerCode();
93	        if (code == null) {
94	            return null;
95	        }
96	        int dash = code.indexOf('-');
97	        String region = dash >= 0 ? code.substring(0, dash) : code;
98	        return "UNKNOWN".equals(region) ? null : region;
99	    }
100	
101	    /**
102	     * Fixed region-to-timezone table: the IANA timezone name each known region maps to
103	     * ({@code NSW -> Australia/Sydney}, {@code VIC -> Australia/Melbourne},
104	     * {@code QLD -> Australia/Brisbane}). A region absent from this table has no known timezone.
105	     */
106	    java.util.Map<String, String> REGION_TIMEZONES = java.util.Map.of(
107	        "NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
108	
109	    /**
110	     * Derives the owner's IANA timezone from the region its identity carries (see
111	     * {@link #localityRegion(Owner)}) using the fixed region-to-timezone table
112	     * ({@code NSW -> Australia/Sydney}, {@code VIC -> Australia/Melbourne},
113	     * {@code QLD -> Australia/Brisbane}). Returns {@code null} when the owner has no known region
114	     * or the region has no timezone entry, leaving {@code timezone} absent from the response.
115	     */
116	    default String timezone(Owner owner) {
117	        if (owner == null) {
118	            return null;
119	        }
120	        String region = localityRegion(owner);
121	        return region == null ? null : REGION_TIMEZONES.get(region);
122	    }
123	
124	    /**
125	     * Formats an owner's stored names as {@code 'LastName, FirstName'}.
126	     */
127	    default String displayName(Owner owner) {
128	        if (owner == null) {
129	            return null;
130	        }
131	        return owner.getLastName() + ", " + owner.getFirstName();
132	    }
133	
134	    /**
135	     * Returns the owner's initials as the upper-cased first letters of firstName and
136	     * lastName, dot-separated with a trailing dot, e.g. {@code 'J.S.'}.
137	     */
138	    default String initials(Owner owner) {
139	        if (owner == null) {
140	            return null;
141	        }
142	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
143	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
144	    }
145	
146	    Owner toOwner(OwnerDto ownerDto);
147	
148	    @Mapping(target = "id", ignore = true)
149	    @Mapping(target = "pets", ignore = true)
150	    Owner toOwner(OwnerFieldsDto ownerDto);
151	
152	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
153	
154	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
155	
156	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
157	        OwnerPageDto ownerPageDto = new OwnerPageDto();
158	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
159	        ownerPageDto.setPage(ownerPage.getNumber());
160	        ownerPageDto.setSize(ownerPage.getSize());
